package main

import (
	"bufio"
	"fmt"
	"os"
	"strconv"
)

func main() {
	scanner := bufio.NewScanner(os.Stdin)
	scanner.Split(bufio.ScanWords)

	scanner.Scan()
	n, _ := strconv.ParseInt(scanner.Text(), 10, 64)
	scanner.Scan()
	k, _ := strconv.ParseInt(scanner.Text(), 10, 64)

	if k <= n+1 {
		fmt.Println((k - 1) / 2)
		return
	}

	if k >= n*2 {
		fmt.Println(0)
		return
	}

	fmt.Println(n - k/2)
}

